19const determineOutcome = (computerChoice, userChoice) => {
20    if (computerChoice === userChoice) {
21        return "Draw";
22    } else if (computerChoice === "rock" && userChoice === "paper") {
23        return "Win";
24    } else if (computerChoice === "paper" && userChoice === "scissors") {
25        return "Win";
26    } else if (computerChoice === "scissors" && userChoice === "rock") {
27        return "Win";
28    } else {
29        return "Lose";
30    }
31};
